    ('91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Quiz — Le verbe en deuxième position, et le reste autour', 'Allemand', '1re', 'La syntaxe de la phrase déclarative', '47eb5f64-cc34-5aaf-8d10-79aadd8276bb'::uuid),
    ('6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Quiz — Question fermée, question ouverte, question indirecte', 'Allemand', '1re', 'La phrase interrogative', '30fd256e-8e21-53ee-8cf5-2941960e9833'::uuid),
    ('056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Quiz — Choisir entre nicht et kein, et savoir où le poser', 'Allemand', '1re', 'La négation dans la phrase (nicht / kein)', 'e7c719c4-2d4c-5374-822e-531592eedd0d'::uuid),
    ('64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Quiz — La conjonction envoie le verbe à la fin', 'Allemand', '1re', 'La phrase subordonnée', 'c2dbb597-5530-5c08-a0c1-5d2a2d54e890'::uuid),
    ('a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Quiz — Le genre vient d’avant, le cas vient d’après', 'Allemand', '1re', 'La phrase subordonnée relative', 'a6ebe61e-0a9a-5489-8a91-e89c47c7e276'::uuid),
    ('223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Quiz — werden + participe II, et le fameux worden', 'Allemand', '1re', 'La phrase à la voix passive', '0a78c76f-5d0d-5685-a22f-fc185f0f97d8'::uuid),
    ('b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Quiz — zu + infinitif, et les cas où zu disparaît', 'Allemand', '1re', 'La proposition infinitive', '382d5465-0f24-51e5-b5a0-c71c664aaae3'::uuid),
    ('e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Quiz — der, die, das — ein, eine, ein', 'Allemand', '1re', 'Les déterminants définis et indéfinis sujets', '2d349865-725f-5d0a-9b1d-0d780c867901'::uuid),
    ('61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Quiz — Quatre cas, deux familles de déterminants', 'Allemand', '1re', 'Les déterminants et leurs déclinaisons', 'b022aa0b-c33b-5680-9415-5f810f205782'::uuid),
    ('ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Quiz — ich, mich, mir — et l’ordre des pronoms', 'Allemand', '1re', 'Les pronoms personnels', 'f57249e8-f2a3-57f8-bf8c-29fff0b5e486'::uuid),
    ('0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, 'Quiz — dieser, jener — et le der qui montre du doigt', 'Allemand', '1re', 'Les pronoms démonstratifs', 'ac27d77f-d02e-513e-bab0-e5ed1f28487e'::uuid),
    ('c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Quiz — Cinq façons de faire un pluriel', 'Allemand', '1re', 'Le pluriel des noms', '9a61284c-56c5-5004-b5cb-21c5e3cfff29'::uuid),
    ('d4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Quiz — Après sein, werden et bleiben : rien ne bouge', 'Allemand', '1re', 'L’adjectif attribut', '47c5c49e-e45a-5c15-bdf3-3f13f230b852'::uuid),
    ('619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Quiz — Faible, mixte, forte : qui porte la marque du cas', 'Allemand', '1re', 'L’adjectif épithète et ses déclinaisons', '0e540f40-ab22-58d6-985c-e7282fd922fa'::uuid),
    ('3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Quiz — sein ou ihr : c’est le possesseur qui décide', 'Allemand', '1re', 'L’adjectif possessif', '4f53dfdc-a8f7-58bc-aec1-27bd8728d781'::uuid),
    ('59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Quiz — Peters Auto, das Auto des Vaters, das Auto von Peter', 'Allemand', '1re', 'Le génitif saxon', '0e29d074-ed01-5f19-b2ef-4f3358a6cac7'::uuid),
    ('e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Quiz — -er, als, so… wie', 'Allemand', '1re', 'Le comparatif', '33db8cb4-c22c-53ca-88ad-a766e4d4fa96'::uuid),
    ('f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Quiz — am schnellsten ou der schnellste', 'Allemand', '1re', 'Le superlatif', 'b15399a3-00b8-5d56-8a1b-962a2b44735b'::uuid),
    ('9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Quiz — durch, für, gegen, ohne, um', 'Allemand', '1re', 'Les prépositions suivies de l’accusatif', '3bdf7846-a266-5cb6-9b9a-f30cb5f87ec0'::uuid),
    ('d4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Quiz — aus, bei, mit, nach, seit, von, zu', 'Allemand', '1re', 'Les prépositions suivies du datif', '600a7b66-1d5b-567c-813f-53e224481615'::uuid),
    ('4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'Quiz — wo ? datif — wohin ? accusatif', 'Allemand', '1re', 'Les prépositions mixtes', '693fff32-82ea-5409-836c-d8cff9f8e668'::uuid),
    ('0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Quiz — Cinq mots qui ne touchent pas à l’ordre des mots', 'Allemand', '1re', 'Les conjonctions de coordination', '610ab422-bdac-5bea-b042-3b06e348c69b'::uuid),
    ('b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Quiz — wo, wohin, woher — trois questions, trois constructions', 'Allemand', '1re', 'Les compléments de lieu (locatif / directionnel)', '825ac910-be15-5f4c-aeb5-489ad65a5bad'::uuid),
    ('39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Quiz — am, im, um — et l’accusatif sans préposition', 'Allemand', '1re', 'Les compléments de temps', '5c202146-98ca-50fa-b3a9-7e395203bb9b'::uuid),
    ('58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Quiz — sein, haben, werden : trois verbes, six emplois', 'Allemand', '1re', 'Les auxiliaires', 'e054a614-d644-5397-a749-36a33e2e50d0'::uuid),
    ('164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Quiz — Trois formes à retenir par verbe', 'Allemand', '1re', 'Les verbes faibles et les verbes forts', 'f2caf784-7945-5aa6-a8cf-23a5d820f4ef'::uuid),
    ('d1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Quiz — Six verbes qui changent le sens de la phrase', 'Allemand', '1re', 'Les verbes de modalité', '73708e4d-fc0f-5d9a-b24f-c2ab105c810f'::uuid),
    ('ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Quiz — Le préverbe part à la fin — sauf quand il ne part pas', 'Allemand', '1re', 'Les verbes à préverbe séparable', '204eb17f-190f-546f-99aa-5094dc496456'::uuid),
    ('b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Quiz — sich, à l’accusatif ou au datif', 'Allemand', '1re', 'Les verbes pronominaux', '95a77987-5c98-5d5c-918a-229212c8dd4e'::uuid),
    ('f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Quiz — Un seul présent, et il dit aussi le futur', 'Allemand', '1re', 'L’indicatif présent', '52e9e285-6afd-50f9-9755-b03e23d502c7'::uuid),
    ('941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quiz — Le passé de l’écrit et du récit', 'Allemand', '1re', 'Le prétérit', 'da4ca347-0b0c-5a4d-ad4c-fa81da68f5f8'::uuid),
    ('67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Quiz — Le passé qu’on parle', 'Allemand', '1re', 'Le parfait', '6126a8ba-17fc-5d88-873e-98eb817af04a'::uuid),
    ('13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Quiz — werden + infinitif, et le présent qui suffit souvent', 'Allemand', '1re', 'Le futur', '8496b6be-3a2a-5db4-9a82-ce880f3df964'::uuid),
    ('3404fcd9-51b2-573b-bc91-c69d8cf0c16e'::uuid, 'Quiz — Trois personnes, trois formes', 'Allemand', '1re', 'L’impératif', '0b4b000c-79df-5c5b-92f8-3ce9842b5364'::uuid),
    ('6458826f-43cd-56af-b3f7-c8198bdfb159'::uuid, 'Quiz — würde, hätte, wäre : l’irréel et la politesse', 'Allemand', '1re', 'Le subjonctif II présent', 'efa95ec5-958a-5a3d-bbe7-c8d166d999c8'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('4b0f5ee4-7230-5254-8c10-4661de8620d8'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Devant une subordonnée introduite par « dass », la virgule est…', 'mcq', '["Obligatoire","Facultative","Interdite","Remplacée par un tiret"]'::jsonb, 0, 'La virgule allemande sépare des propositions : *Ich weiß, dass er kommt.*', 1),
    ('721cf3a4-b30c-5c24-aff8-0c74d466c663'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'En allemand, on met une virgule devant « und » dans une énumération.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pas de virgule devant *und* ni *oder* ; mais elle est obligatoire devant *aber*, *sondern* et *denn*.', 2),
    ('28337da1-d251-574f-a8d3-afb5dbba15dc'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Comment s’écrivent les guillemets allemands ?', 'mcq', '["En bas à l’ouverture, en haut à la fermeture","Avec des chevrons, comme en français","Les deux en haut, comme en anglais","Ils n’existent pas"]'::jsonb, 0, '*Er sagt: „Ich komme.“* — et deux-points avant le discours direct.', 3),
    ('f42e97fe-978d-50c6-be83-dad39e784c84'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Quel groupe infinitif exige une virgule ?', 'mcq', '["Celui introduit par um… zu","Tout groupe contenant zu","Aucun groupe infinitif","Seulement celui introduit par dass"]'::jsonb, 0, '*Ich lerne, um zu bestehen.* Idem pour *ohne… zu* et *statt… zu*.', 4),
    ('d6db86e2-2c90-5d88-ad40-21a670d2b1fa'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Un adjectif substantivé prend la majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*das Wichtigste*, *das Neue* : dès qu’un mot devient nom, il prend la majuscule.', 5),
    ('aab38859-6931-51c6-96ab-82b0d63b1d7a'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Qu’est-ce qui distingue « Sie » de « sie » à l’écrit ?', 'mcq', '["La majuscule du vouvoiement","L’accent sur le e","Rien du tout","La place dans la phrase"]'::jsonb, 0, 'Le *Sie* de politesse et ses formes (*Ihnen*, *Ihr*) gardent la majuscule.', 6),
    ('3ef8d500-cf45-516e-b068-41bf9fb75a7b'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Après une voyelle brève, on écrit…', 'mcq', '["ss, comme dans Fluss et dass","ß, comme dans Fluß et daß","un s simple","sz"]'::jsonb, 0, '*ß* est réservé aux voyelles longues et aux diphtongues : *Straße*, *heißen*.', 7),
    ('2770aefc-8f8e-5472-9adf-c78cbb2a59e4'::uuid, '01bcd942-fc6a-50cf-8fab-bd0e23f5bc9e'::uuid, 'Une subordonnée enchâssée dans la principale est encadrée de deux virgules.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das Buch, das ich lese, ist spannend.*', 8),
    ('f9c8a090-69b2-5084-b4b6-fa4ca8a3249d'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Dans une déclarative allemande, le verbe conjugué occupe…', 'mcq', '["La deuxième place","La première place","La dernière place","N’importe quelle place"]'::jsonb, 0, 'La deuxième POSITION, c’est-à-dire le deuxième groupe, pas le deuxième mot.', 1),
    ('94161f69-dfb8-57e2-854f-ebe4a5a26b0c'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, '« Heute er geht ins Kino » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand un autre élément ouvre la phrase, le sujet passe après le verbe : *Heute geht er…*', 2),
    ('383ad450-ae88-5996-8870-0b861da104a9'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Où se place l’infinitif dépendant d’un verbe de modalité ?', 'mcq', '["À la fin de la phrase","Juste après le modal","En première position","Avant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : *Ich muss heute Abend arbeiten.*', 3),
    ('2edae7cd-a6ae-5e36-b9fc-ee8c9884533b'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Que signifie l’ordre TeKaMoLo ?', 'mcq', '["Temps, cause, manière, lieu","Temps, lieu, cause, manière","Lieu, temps, cause, manière","Cause, lieu, temps, manière"]'::jsonb, 0, '*Ich fahre morgen wegen der Arbeit mit dem Zug nach München.*', 4),
    ('c7705358-d023-57a7-a620-ba91b34f2e30'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Avec deux groupes nominaux, l’ordre est datif puis accusatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich gebe dem Kind das Buch.* L’ordre s’inverse si l’accusatif est un pronom.', 5),
    ('95232aad-f607-5764-848d-d20fba5c88b3'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Comment traduire « Je le donne à l’enfant » ?', 'mcq', '["Ich gebe es dem Kind","Ich gebe dem Kind es","Ich es gebe dem Kind","Ich gebe dem es Kind"]'::jsonb, 0, 'Le pronom accusatif remonte devant le groupe au datif.', 6),
    ('e451ec0c-c536-5b70-a1b1-d5dd0f7669d3'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, 'Dans « Ich stehe um sieben Uhr auf », « auf » est…', 'mcq', '["Le préverbe séparable, rejeté en fin de phrase","Une préposition de lieu","Un adverbe de temps","Une faute de frappe"]'::jsonb, 0, '*aufstehen* : le préverbe ferme la parenthèse verbale.', 7),
    ('f06dba19-778b-58f4-9436-052f043803be'::uuid, '91002c01-3946-531e-87fa-bfcc7f398ca1'::uuid, '« Nach Berlin fahre ich morgen » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'N’importe quel groupe peut occuper la première place, tant que le verbe garde la deuxième.', 8),
    ('45bdfe0b-9755-5e76-8778-783e88402b74'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Dans une question fermée, où se place le verbe conjugué ?', 'mcq', '["En première position","En deuxième position","À la fin de la phrase","Juste après le sujet"]'::jsonb, 0, '*Kommst du morgen?* La réponse attendue est *ja*, *nein* ou *doch*.', 1),
    ('ac842101-8d1c-5e9c-b07b-93c967f51a77'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Dans une question ouverte, le verbe reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot en *w-* occupe la première place : *Wann kommst du?*', 2),
    ('6c4cecac-84b1-531f-a33a-5d8af70f57cd'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Quelle est la forme accusative de « wer » ?', 'mcq', '["wen","wem","wessen","was"]'::jsonb, 0, '*Wen siehst du?* — *wem* est le datif, *wessen* le génitif.', 3),
    ('744f2669-d4e1-524e-9f93-0425182b178a'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Comment répondre « si ! » à « Du kommst nicht mit? »', 'mcq', '["Doch!","Ja!","Nein!","So!"]'::jsonb, 0, 'Après une question négative, *ja* est impossible : c’est *doch* qui contredit.', 4),
    ('f0c31b2e-aae9-5cd5-9ea8-7fd0477ab478'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Dans une question indirecte, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En première position","En deuxième position","Devant le sujet"]'::jsonb, 0, '*Ich weiß nicht, wann er kommt.*', 5),
    ('793a9beb-5a54-561f-b73d-382edecb3dad'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Le « si » d’une question indirecte se traduit par « wenn ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *ob* : *Ich frage mich, ob er kommt.* *wenn* introduit une condition ou un moment.', 6),
    ('14af21c4-6689-5639-9c45-7cf8c49dff66'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Que demande « wohin » ?', 'mcq', '["La destination d’un déplacement","Le lieu où l’on se trouve","Le lieu d’où l’on vient","La cause"]'::jsonb, 0, '*wo* = sans mouvement, *wohin* = vers où, *woher* = d’où.', 7),
    ('c20adec6-83e4-59f9-94fb-8c433cd4d9cb'::uuid, '6174fc5d-3702-50d2-b513-fdd5cf50ed94'::uuid, 'Comment demander « À quoi penses-tu ? »', 'mcq', '["Woran denkst du?","An was denkst du nicht?","Wen denkst du?","Wo denkst du?"]'::jsonb, 0, 'Pour une CHOSE, l’allemand soude *wo(r)-* et la préposition.', 8),
    ('e904b02d-1f32-586f-9775-ceb7a2cfcd5e'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Comment nier « Ich habe ein Auto » ?', 'mcq', '["Ich habe kein Auto","Ich habe nicht ein Auto","Ich habe nicht Auto","Ich habe ein Auto nicht"]'::jsonb, 0, 'Devant un nom avec *ein* ou sans article, c’est *kein*.', 1),
    ('343c146f-8b5a-579d-af72-73a1e2f7c4c7'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Comment nier « Ich kenne den Mann » ?', 'mcq', '["Ich kenne den Mann nicht","Ich kenne keinen Mann","Ich kenne den Mann kein","Ich nicht kenne den Mann"]'::jsonb, 0, 'Le nom porte un article défini : la négation est *nicht*, rejetée à droite.', 2),
    ('62a990c4-f63e-5c98-9de2-5b6e0a1f8b5b'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, '« kein » se décline comme « ein » et possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*keine Freunde*, *keinen Kaffee*, *keinem Kind*.', 3),
    ('b7e0b96f-9c08-523d-aa03-7dc382f99241'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Où se place « nicht » par rapport à un attribut ?', 'mcq', '["Devant l’attribut","Après l’attribut","En fin de phrase","Devant le sujet"]'::jsonb, 0, '*Das Buch ist nicht interessant.*', 4),
    ('60d9cf2a-647f-5b5c-98c7-c24f654ae9a1'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Dans « Ich habe ihn gestern nicht gesehen », « nicht » se place…', 'mcq', '["Devant le participe passé","Après le participe passé","Juste après l’auxiliaire","En première position"]'::jsonb, 0, '*nicht* va le plus à droite possible, mais reste devant le second morceau du verbe.', 5),
    ('6f3a09b4-3133-50c0-b08a-ac9ec2d9dfd2'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'En allemand, la double négation renforce la négation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule négation suffit : *Ich sehe nichts.* C’est l’espagnol qui double.', 6),
    ('5570df63-00f1-5e00-9e2e-512e73b44162'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Que signifie « nicht mehr » ?', 'mcq', '["Ne… plus","Pas encore","Jamais","Nulle part"]'::jsonb, 0, '*noch nicht* signifie « pas encore ».', 7),
    ('5aa3cf24-0358-5b8d-a15d-1d42fe153be8'::uuid, '056abac8-6966-585e-9bbc-ea1ec26be2b5'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["sondern","aber","denn","oder"]'::jsonb, 0, '*Er ist nicht Deutscher, sondern Österreicher.* *aber* oppose sans rectifier.', 8),
    ('d563dde2-90f0-5b60-905a-69082e2cf9c2'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Dans une subordonnée, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En deuxième position","Juste après la conjonction","En première position"]'::jsonb, 0, '*Ich bleibe zu Hause, weil ich krank bin.*', 1),
    ('645e17d2-cef5-51f2-8e9c-005ca16462d0'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Dans « …, weil ich gearbeitet habe », quel mot ferme la phrase ?', 'mcq', '["L’auxiliaire conjugué habe","Le participe gearbeitet","Le sujet ich","La conjonction weil"]'::jsonb, 0, 'Le verbe CONJUGUÉ passe après le participe : c’est propre à la subordonnée.', 2),
    ('3893266a-50cf-5575-acb1-79d765724f8c'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, '« denn » envoie le verbe à la fin, comme « weil ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*denn* est une conjonction de coordination : *Ich bleibe zu Hause, denn ich bin krank.*', 3),
    ('3448887f-9597-52c6-a5d2-767424cd107b'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Si la subordonnée ouvre la phrase, que se passe-t-il dans la principale ?', 'mcq', '["Le verbe suit immédiatement la virgule","Le sujet suit immédiatement la virgule","Rien ne change","La principale perd son verbe"]'::jsonb, 0, '*Weil ich krank bin, bleibe ich zu Hause.* La subordonnée occupe la première position.', 4),
    ('d2aafb63-117c-5004-a076-5c4516d3fa39'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Quelle conjonction traduit « quand » pour un fait unique du passé ?', 'mcq', '["als","wenn","wann","ob"]'::jsonb, 0, '*Als ich zehn Jahre alt war…* — *wenn* vaut pour la répétition ou le présent.', 5),
    ('fd74e10e-1071-5643-85a5-45457e3214e2'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, '« wann » peut introduire une subordonnée de temps ordinaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*wann* n’apparaît que dans une question, directe ou indirecte.', 6),
    ('dcf7a71c-cac6-5252-987d-353dcc869934'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Que signifie « obwohl » ?', 'mcq', '["Bien que","Parce que","Pour que","Depuis que"]'::jsonb, 0, '*Obwohl es regnet, gehe ich spazieren.*', 7),
    ('d5201082-2b72-58ec-89f2-9577651caaab'::uuid, '64bb6410-63b5-5dc9-ba84-5e40759ea8b3'::uuid, 'Quelle conjonction exprime le but ?', 'mcq', '["damit","weil","obwohl","nachdem"]'::jsonb, 0, '*Ich lerne, damit ich das Abitur bestehe.*', 8),
    ('349d8852-8f47-5a78-949d-9067e53d7c9f'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Le pronom relatif prend son genre de l’antécédent et son cas…', 'mcq', '["De sa fonction dans la relative","De la fonction de l’antécédent","Du verbe de la principale","Il ne prend jamais de cas"]'::jsonb, 0, 'C’est le raisonnement en deux temps : genre avant, cas après.', 1),
    ('307242b7-0e91-5657-a7e2-362abd2a5525'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Comment traduire « l’homme que je vois » ?', 'mcq', '["Der Mann, den ich sehe","Der Mann, der ich sehe","Der Mann, dem ich sehe","Der Mann, dessen ich sehe"]'::jsonb, 0, 'Masculin + fonction de COD → accusatif *den*.', 2),
    ('0ce06cf9-aefa-5290-9faf-798a125d5e93'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Quelle est la forme du relatif au datif pluriel ?', 'mcq', '["denen","den","deren","die"]'::jsonb, 0, '*Die Freunde, denen ich helfe.* C’est l’une des trois formes qui diffèrent de l’article.', 3),
    ('0c29363d-1dd8-59e5-af3d-97eedf01939b'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Dans une relative, le verbe conjugué reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La relative est une subordonnée : le verbe conjugué ferme la proposition.', 4),
    ('b3f355b4-77eb-5ada-81d4-cdcecff9a844'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Où se place la préposition dans une relative ?', 'mcq', '["Devant le pronom relatif","À la fin de la relative","Après le verbe","Elle disparaît"]'::jsonb, 0, '*Die Stadt, in der ich wohne.* Et c’est elle qui commande le cas.', 5),
    ('553468c5-909b-5ade-97cf-e7af78850946'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Comment traduire « l’homme dont la voiture est en panne » ?', 'mcq', '["Der Mann, dessen Auto kaputt ist","Der Mann, deren Auto kaputt ist","Der Mann, den Auto kaputt ist","Der Mann, wessen Auto kaputt ist"]'::jsonb, 0, 'Génitif masculin *dessen*, et le nom qui suit n’a pas d’article.', 6),
    ('142145d9-d3a6-5702-adeb-33fe8b2f3c6c'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, 'Après « alles », « nichts » ou « etwas », le relatif est…', 'mcq', '["was","das","wer","dessen"]'::jsonb, 0, '*Alles, was du sagst, ist richtig.*', 7),
    ('a8976afa-0593-5b7c-abbf-a05d239ed988'::uuid, 'a5763203-410a-520c-93bf-edb7f7822e60'::uuid, '« deren » sert au génitif féminin et au génitif pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Die Frau, deren Sohn…* / *Die Leute, deren Kinder…*', 8),
    ('110c9884-7819-5e89-8485-9475f2717520'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Avec quel auxiliaire se construit le passif d’action ?', 'mcq', '["werden","sein","haben","lassen"]'::jsonb, 0, '*Das Haus wird gebaut.* C’est *sein* qui donne le passif d’état.', 1),
    ('1453a64d-576f-5e44-99b4-dbb402be4d8a'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Comment dit-on « la maison a été construite » ?', 'mcq', '["Das Haus ist gebaut worden","Das Haus ist gebaut geworden","Das Haus hat gebaut worden","Das Haus war gebaut"]'::jsonb, 0, 'Au parfait du passif, le participe de *werden* perd son *ge-* : *worden*.', 2),
    ('fc335a5e-3136-5c63-9b81-22002c33daef'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, '« Das Haus ist gebaut » exprime…', 'mcq', '["Un résultat, un état","Une action en cours","Un futur","Une supposition"]'::jsonb, 0, 'C’est le passif d’état : la photo, pas le film.', 3),
    ('9c7ea51b-362e-5997-bfcc-0b05785095a3'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Quel mot introduit l’agent quand c’est une personne ?', 'mcq', '["von + datif","durch + accusatif","mit + datif","für + accusatif"]'::jsonb, 0, '*Das Buch wurde von Goethe geschrieben.* *durch* introduit un moyen.', 4),
    ('e3cca146-c081-58a9-9a54-015d9ef28837'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'L’allemand peut mettre au passif un verbe sans complément d’objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le passif impersonnel : *Hier wird getanzt.*', 5),
    ('a9f67c24-4d0d-555c-90f6-9afeb2307763'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Comment traduire « le travail doit être fait aujourd’hui » ?', 'mcq', '["Die Arbeit muss heute gemacht werden","Die Arbeit muss heute gemacht worden","Die Arbeit wird heute machen müssen","Die Arbeit ist heute gemacht müssen"]'::jsonb, 0, 'Le modal se conjugue, le passif passe à l’infinitif en fin de phrase.', 6),
    ('bfa8d79b-8d30-528d-8e97-f434c3b9b06b'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, '« Er ist Arzt geworden » contient un passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *werden* employé seul, au sens de « devenir » — d’où *geworden* et non *worden*.', 7),
    ('f73dbea5-9679-5c22-bd3e-7b843000087b'::uuid, '223c761e-a32d-5cee-a04a-80da5e5ab7cd'::uuid, 'Quelle tournure active remplace souvent le passif à l’oral ?', 'mcq', '["man + verbe actif","es gibt","sein + zu","lassen"]'::jsonb, 0, '*Man baut ein Haus* est plus courant que *Ein Haus wird gebaut.*', 8),
    ('02bea6e3-0e86-535b-b493-89cb4e678ba6'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Où se place « zu » avec un verbe à préverbe séparable ?', 'mcq', '["Entre le préverbe et le radical, en un seul mot","Devant le préverbe","Après l’infinitif","Il disparaît"]'::jsonb, 0, '*einzukaufen*, *aufzustehen*, *anzurufen*.', 1),
    ('423d0bb2-191b-5957-8578-9f4482528304'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Après un verbe de modalité, l’infinitif prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Ich kann schwimmen.* Les modaux, *sehen*, *hören* et *lassen* refusent *zu*.', 2),
    ('76a3dc75-9d69-57be-9a2d-5837852676b0'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Comment traduire « J’apprends l’allemand pour étudier à Berlin » ?', 'mcq', '["Ich lerne Deutsch, um in Berlin zu studieren","Ich lerne Deutsch, für in Berlin studieren","Ich lerne Deutsch zu studieren in Berlin","Ich lerne Deutsch, damit in Berlin zu studieren"]'::jsonb, 0, '*um… zu* exprime le but, avec virgule obligatoire.', 3),
    ('eea4222a-90bd-592f-9dbe-e942b4eb2a58'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Quand faut-il employer « damit » plutôt que « um… zu » ?', 'mcq', '["Quand les deux propositions n’ont pas le même sujet","Quand la phrase est négative","Quand le verbe est séparable","Jamais"]'::jsonb, 0, '*Ich erkläre es, damit du es verstehst.*', 4),
    ('3369e2c7-7cb2-5dd7-95f1-8252c4ddf6a8'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Que signifie « ohne etwas zu sagen » ?', 'mcq', '["Sans rien dire","Au lieu de parler","Pour ne rien dire","En disant quelque chose"]'::jsonb, 0, '*statt… zu* signifie « au lieu de ».', 5),
    ('c55eb892-da61-5a93-a867-00dd56b6929b'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, '« Ich habe viel zu tun » signifie…', 'mcq', '["J’ai beaucoup à faire","Je dois être fait","Je fais beaucoup","J’aime beaucoup faire"]'::jsonb, 0, '*haben + zu* a une valeur active ; *sein + zu* une valeur passive.', 6),
    ('d2e964ed-e5f7-5748-9693-afed11737f08'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, '« Die Arbeit ist heute zu machen » a une valeur passive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle équivaut à *Die Arbeit muss heute gemacht werden.*', 7),
    ('1ba18065-63e3-55d5-b5e5-451b3bc24155'::uuid, 'b4e7a629-c178-5464-9539-b53049db502c'::uuid, 'Après « Ich gehe », le verbe suivant prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les verbes de mouvement s’en passent : *Ich gehe schwimmen.*', 8),
    ('6b0f7d94-8b76-57d3-9e45-d9bac28e5571'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Quel est l’article défini neutre ?', 'mcq', '["das","der","die","den"]'::jsonb, 0, '*das Buch*, *das Haus*, *das Kind*.', 1),
    ('f739a0e1-b570-56c1-ad9a-c343a976f3ae'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Au pluriel, l’article défini est « die » pour les trois genres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*die Männer*, *die Frauen*, *die Kinder*.', 2),
    ('3d475bbc-0d26-5d50-b5fa-eb395a421d36'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Quel est le genre de « Mädchen » ?', 'mcq', '["Neutre","Féminin","Masculin","Il n’en a pas"]'::jsonb, 0, 'Tous les diminutifs en *-chen* et *-lein* sont neutres, quel que soit le sens.', 3),
    ('f9d59328-9bcf-59a4-8e56-86145663adb0'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Les noms en -ung sont généralement…', 'mcq', '["Féminins","Masculins","Neutres","Sans genre"]'::jsonb, 0, '*die Zeitung*, *die Wohnung*, *die Meinung*. Comme les noms en *-heit* et *-keit*.', 4),
    ('5924be7a-5474-5c0a-944b-41408b2051d7'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'L’article indéfini « ein » possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit simplement *Ich sehe Kinder*. Seule sa négation *kein* a un pluriel.', 5),
    ('73cd8ae2-831d-5f9a-9dba-c41b09ec7e71'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'À quel cas se met le sujet de la phrase ?', 'mcq', '["Au nominatif","À l’accusatif","Au datif","Au génitif"]'::jsonb, 0, 'C’est la forme du dictionnaire : *Der Hund schläft.*', 6),
    ('10096c8f-2622-564e-9da7-cfd7a59d60e9'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Comment traduire « il est professeur » ?', 'mcq', '["Er ist Lehrer","Er ist ein Lehrer","Er ist der Lehrer","Er ist einen Lehrer"]'::jsonb, 0, 'Pas d’article devant un nom de métier après *sein* ou *werden*.', 7),
    ('3b543d6e-e172-5e5b-9418-716bce9189c7'::uuid, 'e5a76567-a1b9-52a8-9dec-58d8f774ad40'::uuid, 'Dans « Das ist mein Buch », « das » est un article neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un démonstratif invariable qui signifie « ça » : il ne s’accorde à rien.', 8),
    ('b36e7ae0-e2ad-507d-b058-f49ff66f5017'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'À quel cas se met le complément d’objet direct ?', 'mcq', '["À l’accusatif","Au datif","Au nominatif","Au génitif"]'::jsonb, 0, 'Le datif est celui du complément d’objet second.', 1),
    ('be7b4c00-ffbd-50c6-a563-e838c38611f5'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Que devient « der » au datif ?', 'mcq', '["dem","den","des","der"]'::jsonb, 0, '*mit dem Mann*. *den* est l’accusatif, *des* le génitif.', 2),
    ('0f55c920-fd0d-5d22-8199-41bb3394d9d9'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Que devient « die » (féminin) au datif ?', 'mcq', '["der","dem","den","die"]'::jsonb, 0, 'Piège classique : *der* est à la fois le masculin nominatif et le féminin datif.', 3),
    ('bfef9e44-db07-5161-81c8-81453dbb2e0b'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Au datif pluriel, le nom prend un -n supplémentaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*mit den Kindern*, *aus den Ländern*.', 4),
    ('4bf5fda5-8749-56aa-a59a-3dd9ffa1cc3e'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Les possessifs se déclinent comme…', 'mcq', '["ein et kein","l’article défini","les adjectifs forts","ils ne se déclinent pas"]'::jsonb, 0, 'D’où leur nom de « déterminants en ein- » : *meinen Bruder*, *meiner Schwester*.', 5),
    ('4bd11da5-df93-53ae-8e5c-706d54196027'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, '« dieser » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*. Comme *jeder* et *welcher*.', 6),
    ('9bd2c90b-0ac1-536a-a01a-1c831b19ab0d'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Au génitif masculin, le nom prend…', 'mcq', '["-(e)s","-n","-er","rien du tout"]'::jsonb, 0, '*das Auto des Vaters*, *das Ende des Jahres*.', 7),
    ('45a116a3-9f38-5b3c-b456-1d2477e08517'::uuid, '61b67454-2a6e-50b9-b1e4-59e6582605bb'::uuid, 'Quel genre change entre le nominatif et l’accusatif ?', 'mcq', '["Le masculin seul","Le féminin seul","Le neutre seul","Les trois genres"]'::jsonb, 0, '*der* → *den*, *ein* → *einen*. Féminin, neutre et pluriel ne bougent pas.', 8),
    ('db58ae18-2b5c-5d1b-96eb-a1518bea0d09'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Quel est le pronom accusatif de « er » ?', 'mcq', '["ihn","ihm","sie","es"]'::jsonb, 0, '*Ich sehe ihn.* *ihm* est le datif.', 1),
    ('5f73c685-9b26-5546-979a-172609e2c56f'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Comment reprendre « der Tisch » par un pronom ?', 'mcq', '["er","es","sie","ihn"]'::jsonb, 0, 'Le genre GRAMMATICAL commande : un objet masculin se reprend par *er*.', 2),
    ('a9e12e5b-118f-52e4-9029-cf15eef3dc84'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Quel est le pronom datif de « sie » (elle) ?', 'mcq', '["ihr","ihn","ihnen","sie"]'::jsonb, 0, '*Ich helfe ihr.* Ne pas le confondre avec *ihr* = vous (2e personne du pluriel).', 3),
    ('cb0fd62b-a6af-59b7-9978-7f18f762f90e'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Avec deux pronoms compléments, l’ordre est…', 'mcq', '["Accusatif puis datif","Datif puis accusatif","Indifférent","Toujours alphabétique"]'::jsonb, 0, '*Ich gebe es dir* — l’inverse de l’ordre des groupes nominaux.', 4),
    ('30307187-d9e4-54c3-ae1e-9fd2cd01409a'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, '« Sie » de politesse se conjugue comme la 3e personne du pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Können Sie mir helfen?* Et il garde toujours sa majuscule.', 5),
    ('abc2d95c-4a6b-59f9-a47f-6b1da6d90f2d'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Dans « Es regnet », « es » est…', 'mcq', '["Un sujet apparent","Un COD","Un possessif","Une faute"]'::jsonb, 0, 'Comme dans *Es gibt* : un sujet grammatical vide.', 6),
    ('6e041740-d903-508a-8e28-1a88d888e167'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, '« man » se décline « einen » à l’accusatif et « einem » au datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das macht einen müde.* C’est un pronom indéfini, pas un pronom personnel.', 7),
    ('24b6e4cd-3210-586a-ba52-e6f674bee302'::uuid, 'ea989e2e-cad0-5889-a1d6-cd7a54658cee'::uuid, 'Où remontent les pronoms compléments dans la phrase ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Avant le verbe conjugué","Après le participe passé"]'::jsonb, 0, '*Gestern hat mich mein Vater angerufen* : ils peuvent même précéder le sujet nominal.', 8),
    ('cb1d72c8-0767-5e00-bf05-8ace3137e3a9'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, '« dieser » se décline comme…', 'mcq', '["L’article défini","L’article indéfini","Un adjectif fort","Il ne se décline pas"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*.', 1),
    ('50c6a67a-13f4-500a-85ac-509b6ae1a2fa'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, 'Dans « Den kenne ich gut! », « den » est…', 'mcq', '["Un démonstratif accentué","Un article défini","Un pronom relatif","Une préposition"]'::jsonb, 0, 'C’est la forme démonstrative la plus courante à l’oral.', 2),
    ('ae369066-a8a9-501b-997d-21d07b848a7b'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, 'Quelle est la forme du démonstratif au datif pluriel ?', 'mcq', '["denen","den","dessen","deren"]'::jsonb, 0, 'Comme le pronom relatif : *denen* et non *den*.', 3),
    ('a26336ed-c074-5a64-8d33-c9c58fa8ac42'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, '« Ich traf Paul und dessen Bruder » signifie…', 'mcq', '["Le frère de Paul","Mon frère","Le frère de quelqu’un d’autre","Le même frère"]'::jsonb, 0, '*dessen* lève l’ambiguïté que *seinen* laisserait planer.', 4),
    ('2fac2dca-3db1-51c9-b41a-628210398cc0'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, '« derselbe » se décline sur ses deux morceaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in demselben Haus* : *der-* comme l’article, *-selbe* comme un adjectif faible.', 5),
    ('9ec74235-1dd8-5e0c-bb80-a2f2bd319be1'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, 'Comment traduire « Ce sont mes parents » ?', 'mcq', '["Das sind meine Eltern","Die sind meine Eltern","Das ist meine Eltern","Diese sind meine Eltern"]'::jsonb, 0, '*das* reste invariable ; le verbe s’accorde avec ce qui suit.', 6),
    ('fb0399ec-284a-5e9b-8c51-11125c920cb5'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, '« dass » et « das » s’emploient indifféremment.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*dass* est la conjonction « que » ; *das* l’article ou le démonstratif. Test : remplacer par *dieses*.', 7),
    ('f6ff2073-4b0f-5230-b111-13697f5745b5'::uuid, '0e2bb487-7eed-5da9-9666-b9d08bfdf80e'::uuid, '« jener » appartient surtout…', 'mcq', '["À la langue écrite et soutenue","À l’oral familier","Au vocabulaire technique","Au vieil allemand disparu"]'::jsonb, 0, 'À l’oral, on lui préfère *dieser… der da*.', 8),
    ('f3fd1992-3818-5ec7-8519-374aa0881054'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Quel est le pluriel de « das Buch » ?', 'mcq', '["die Bücher","die Buche","die Buchs","die Buchen"]'::jsonb, 0, 'Pluriel en *-er* avec inflexion, typique des neutres.', 1),
    ('ceefdb08-4959-5570-bb74-f81ad63320d3'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'La quasi-totalité des féminins font leur pluriel en…', 'mcq', '["-(e)n","-e","-er","-s"]'::jsonb, 0, '*die Frauen*, *die Blumen*, *die Zeitungen* — et jamais d’inflexion.', 2),
    ('111f05d4-5f86-5a8f-938f-fafd0d180ea5'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, '« der Lehrer » a le même mot au singulier et au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les masculins en *-er*, *-el*, *-en* ne changent pas : seul l’article le dit.', 3),
    ('aa18e4a3-bcd9-58d5-85ce-040c24c0b3c1'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Quel est le pluriel de « das Auto » ?', 'mcq', '["die Autos","die Auten","die Autoer","die Aute"]'::jsonb, 0, 'Les emprunts font leur pluriel en *-s*.', 4),
    ('da1cbc32-ed5a-5b1b-a45d-8fbb222621e7'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Au datif pluriel, que prend le nom ?', 'mcq', '["Un -n s’il n’en a pas déjà un","Un -s","Un -er","Rien"]'::jsonb, 0, '*mit den Kindern*, *aus den Städten* — sauf les pluriels en *-s*.', 5),
    ('ac735c92-d8d8-529b-9cea-226d58a6446a'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Quel est le pluriel de « die Lehrerin » ?', 'mcq', '["die Lehrerinnen","die Lehrerins","die Lehrerine","die Lehrerinen"]'::jsonb, 0, 'Les noms en *-in* doublent le n avant *-en*.', 6),
    ('86b75faf-d24d-5d3b-b3f0-9cd2f1a1f6bd'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, '« die Leute » n’existe qu’au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *die Polizei* ou *die Milch* n’existent qu’au singulier.', 7),
    ('9e0fbacc-d311-5d25-93f5-031f67981d5a'::uuid, 'c14ebe25-5b91-5403-949b-f75d3ee67aeb'::uuid, 'Au pluriel, l’article défini dépend du genre du nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *die* pour les trois genres au nominatif et à l’accusatif.', 8),
    ('bbdcd9fd-490d-55d6-9181-692c07f84291'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Après « sein », l’adjectif attribut…', 'mcq', '["Reste invariable","S’accorde en genre","S’accorde en nombre","Prend toujours -e"]'::jsonb, 0, '*Der Mann ist alt*, *die Frau ist alt*, *die Kinder sind alt*.', 1),
    ('b7259c63-ef8c-5038-be9d-b690f275969e'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, '« Die Frau ist alte » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’attribut ne prend aucune terminaison : *Die Frau ist alt.*', 2),
    ('59faec9b-00d7-594f-a889-0422b301a741'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Quel verbe n’appelle PAS un attribut invariable ?', 'mcq', '["sehen","sein","werden","bleiben"]'::jsonb, 0, '*sein*, *werden* et *bleiben* sont les trois verbes de base de l’attribut.', 3),
    ('534eb063-2b89-51f1-9ef5-e28d25f4d503'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Comment traduire « une vieille femme » ?', 'mcq', '["eine alte Frau","eine alt Frau","ein alte Frau","eine alten Frau"]'::jsonb, 0, 'Devant le nom, l’adjectif est épithète : il se décline.', 4),
    ('54dfa767-c0f1-5ce0-b298-5015b2ed4859'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'En allemand, l’adverbe se forme avec une terminaison spéciale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le même mot sert d’adjectif et d’adverbe : *Er singt schön.*', 5),
    ('1d10d25e-d851-561c-b66f-30e04a36f116'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Dans « Der Zug ist schneller », la terminaison -er marque…', 'mcq', '["Le comparatif","Le masculin","Le pluriel","Le datif"]'::jsonb, 0, 'Ce n’est pas un accord : l’attribut ne s’accorde jamais.', 6),
    ('52fe8775-6f9c-51f1-a18d-7d7f41a1dc88'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'Comment traduire « je trouve le livre intéressant » ?', 'mcq', '["Ich finde das Buch interessant","Ich finde das Buch interessantes","Ich finde das interessante Buch","Ich finde interessant das Buch"]'::jsonb, 0, '*finden* + COD + attribut invariable.', 7),
    ('57fa2e41-3501-58c1-ac40-66c7e10deda2'::uuid, 'd4a1dc70-afea-50f0-907e-7819d3120946'::uuid, 'La différence entre attribut et épithète tient à la place de l’adjectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après le verbe : invariable. Devant le nom : décliné.', 8),
    ('b277db8a-316b-5193-b863-b4a3019ad0b5'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Quand l’adjectif prend-il la déclinaison forte ?', 'mcq', '["Quand aucun déterminant ne porte la marque du cas","Après l’article défini","Après ein et kein","Jamais au pluriel"]'::jsonb, 0, '*kalter Kaffee*, *frische Milch* : l’adjectif prend les terminaisons de l’article défini.', 1),
    ('914d91d6-c2be-5f4a-86dd-d40eedf5366b'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Comment traduire « un vieil homme » (nominatif) ?', 'mcq', '["ein alter Mann","ein alt Mann","ein alten Mann","ein alte Mann"]'::jsonb, 0, '*ein* ne marque pas le masculin nominatif : l’adjectif le fait à sa place.', 2),
    ('989ee216-0b42-5b9b-a785-ecfb796b6be4'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Après « der », l’adjectif prend seulement -e ou -en.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la déclinaison faible : *der alte Mann*, *dem alten Mann*.', 3),
    ('159d7a62-f266-531c-8796-eae399626052'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Comment dit-on « une vieille maison » à l’accusatif (das Haus) ?', 'mcq', '["ein altes Haus","ein alten Haus","eine alte Haus","ein alte Haus"]'::jsonb, 0, 'Neutre accusatif : *ein* ne marque rien, l’adjectif prend *-es*.', 4),
    ('62ac6e51-0770-5287-aa4a-8e5566de2515'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Après « meinem », l’adjectif prend…', 'mcq', '["-en","-er","-es","-e"]'::jsonb, 0, 'Le possessif marque déjà le datif : *meinem alten Freund*.', 5),
    ('8e3e4ecc-4e0d-5af3-ad6b-939172e1a612'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, '« hoch » garde son c devant une terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein hoher Berg*, *das hohe Haus* : le *c* disparaît.', 6),
    ('347d106e-d68d-57a7-9319-b32e74c37a7a'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, 'Que devient « teuer » dans « ein … Auto » ?', 'mcq', '["teures","teueres","teuers","teuer"]'::jsonb, 0, '*teuer* et *dunkel* perdent leur *e* : *ein teures Auto*, *ein dunkles Zimmer*.', 7),
    ('366f555b-66bc-51c4-aade-9027e0ae49d1'::uuid, '619ab08a-f841-571f-b6bb-7f8a56e54a38'::uuid, '« rosa » et « lila » se déclinent comme les autres adjectifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les adjectifs en *-a* sont invariables : *ein rosa Kleid*.', 8),
    ('ffe16edf-959a-5f6d-a0b7-cfa201e20f55'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Comment traduire « Anna et son frère » ?', 'mcq', '["Anna und ihr Bruder","Anna und sein Bruder","Anna und seinen Bruder","Anna und ihre Bruder"]'::jsonb, 0, 'Le radical suit le POSSESSEUR (Anna → *ihr-*), la terminaison l’objet possédé (*Bruder*, masculin).', 1),
    ('fdb2657b-41ec-5daa-ae9c-37e908c65c0f'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Comment traduire « Peter et sa sœur » ?', 'mcq', '["Peter und seine Schwester","Peter und ihre Schwester","Peter und sein Schwester","Peter und ihren Schwester"]'::jsonb, 0, 'Radical *sein-* (Peter), terminaison féminine (*Schwester*).', 2),
    ('d190f580-5283-58ab-85c0-3d20b93a61cc'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Le possessif se décline comme…', 'mcq', '["ein et kein","l’article défini","un adjectif faible","il ne se décline pas"]'::jsonb, 0, 'Avec en plus un pluriel : *meine Freunde*, *meinen Freunden*.', 3),
    ('0be48159-27c5-53cb-ab12-900daccd5d7e'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Que devient « euer » devant une terminaison ?', 'mcq', '["eur-","euer-","eue-","eur-e-"]'::jsonb, 0, '*eure Mutter*, *euren Vater*. *unser*, lui, garde son *e*.', 4),
    ('b1d022ae-9b7c-5bc2-a024-1547b37b0529'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, '« Ihr » avec majuscule signifie « leur ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec majuscule, c’est le possessif de politesse : « votre ».', 5),
    ('ab5453c2-6cdc-5f10-8579-e4896153b7f0'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Comment dit-on « je me lave les mains » ?', 'mcq', '["Ich wasche mir die Hände","Ich wasche meine Hände mir","Ich wasche mich die Hände","Ich wasche meinen Händen"]'::jsonb, 0, 'Avec les parties du corps, l’allemand préfère article + datif au possessif.', 6),
    ('94d1fac5-c100-523f-8d6c-0dc24f0462db'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Employé seul, « mein » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das ist meins*, *Das ist meiner* : il devient pronom possessif.', 7),
    ('ba4819d1-0efb-5957-ba33-8438bab9a0b5'::uuid, '3ef03331-0fd3-5de9-b22b-e43055b1a8ca'::uuid, 'Dans « Das Kind und seine Mutter », pourquoi « seine » ?', 'mcq', '["Parce que « Kind » est neutre, donc radical sein-","Parce que « Mutter » est féminin","Parce que l’enfant est un garçon","Parce que c’est une exception"]'::jsonb, 0, 'Le radical suit le genre GRAMMATICAL du possesseur, pas son sexe.', 8),
    ('e7f2c913-1980-5f99-8941-cf2a543738a9'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Comment dit-on « la voiture de Peter » ?', 'mcq', '["Peters Auto","Peter’s Auto","das Auto Peters","der Peter Auto"]'::jsonb, 0, 'Le nom propre passe devant, avec un *-s* sans apostrophe.', 1),
    ('f7d4a69a-c571-525b-894a-0609d1e25ee5'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Comment dit-on « la voiture du père » ?', 'mcq', '["das Auto des Vaters","das Auto der Vater","des Vaters das Auto","das Auto dem Vater"]'::jsonb, 0, 'Génitif masculin : *des* + nom en *-(e)s*, placé derrière.', 2),
    ('1764ac43-702d-536c-89bb-4d2fe65396ff'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Au génitif féminin, le nom prend un -s.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les masculins et les neutres le prennent : *das Haus der Frau*.', 3),
    ('312641db-3944-5fa6-acef-d24a91cc8d67'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Quelle question introduit le génitif ?', 'mcq', '["Wessen?","Wem?","Wen?","Wo?"]'::jsonb, 0, '*Wessen Buch ist das?*', 4),
    ('ebc9a47e-6a2d-5c4f-97ca-0576bb0d6c99'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","mit","für","bei"]'::jsonb, 0, 'Comme *wegen*, *trotz*, *statt*, *innerhalb* : *während des Sommers*.', 5),
    ('5aecaa93-c50e-5c31-a93b-bef1814668c7'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, '« ein Freund von mir » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*von* + datif remplace le génitif, surtout à l’oral.', 6),
    ('e1ca50cd-e6ce-5cb1-8162-7b10163d3c59'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Le génitif saxon s’écrit avec une apostrophe, comme en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Annas Buch*, sans apostrophe — sauf après un son sifflant : *Thomas’ Auto*.', 7),
    ('135c24d8-6104-5f0b-bd7c-e5b7a38cd094'::uuid, '59ebcbdb-3fb7-5057-bce0-b2cf73367593'::uuid, 'Au génitif pluriel, l’article est…', 'mcq', '["der","des","den","die"]'::jsonb, 0, '*die Bücher der Kinder*, sans marque supplémentaire sur le nom.', 8),
    ('33034fe6-d0dd-5f45-bc5f-1eec10cc8986'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Comment forme-t-on le comparatif d’un adjectif long comme « interessant » ?', 'mcq', '["interessanter","mehr interessant","am interessanten","interessant als"]'::jsonb, 0, 'Quelle que soit la longueur du mot, c’est la terminaison *-er*.', 1),
    ('e74891e2-6e2a-5bfd-b379-87a0835f87b8'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Quel mot introduit le second terme d’une comparaison d’inégalité ?', 'mcq', '["als","wie","wenn","denn"]'::jsonb, 0, '*Peter ist größer als Paul.* *wie* sert à l’égalité.', 2),
    ('36b7be4e-b950-567a-80bb-b45f489a481f'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Comment dit-on « aussi grand que » ?', 'mcq', '["so groß wie","so groß als","größer wie","als groß wie"]'::jsonb, 0, '*so… wie* pour l’égalité, *…-er als* pour l’inégalité.', 3),
    ('256144f9-0d01-52dc-b412-cba9c72bfc78'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Quel est le comparatif de « gut » ?', 'mcq', '["besser","guter","mehr gut","gutter"]'::jsonb, 0, 'Irrégulier, comme *viel → mehr* et *gern → lieber*.', 4),
    ('36603c44-c22d-5159-b6f3-5cc1ef59e726'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, '« Ich trinke lieber Tee » signifie…', 'mcq', '["Je préfère le thé","Je bois beaucoup de thé","Je bois le meilleur thé","J’aimerais du thé"]'::jsonb, 0, '*lieber* est le comparatif de *gern* : c’est ainsi qu’on exprime la préférence.', 5),
    ('97d0ab9a-b69a-590c-8d13-980cbe348d06'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Devant un nom, le comparatif ne se décline pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein größeres Haus*, *mein älterer Bruder* : deux terminaisons se suivent.', 6),
    ('f7ef9ad8-e960-5ef5-9b5c-baf416673985'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, 'Comment dit-on « de plus en plus froid » ?', 'mcq', '["immer kälter","mehr und mehr kalt","so kalt wie","am kältesten"]'::jsonb, 0, '*Es wird immer kälter.* Et *je… desto* pour « plus… plus ».', 7),
    ('5aab3d5f-e543-57b6-ad5f-21ef9eba2bd8'::uuid, 'e81b7a17-60b2-5ab3-814a-8fe043f9f8a0'::uuid, '« mehr groß » est une façon correcte de dire « plus grand ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*mehr* traduit « plus » de quantité ; le comparatif d’un adjectif se fait en *-er*.', 8),
    ('38b1f2b4-85c6-52f6-969a-28f26b631289'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Quelle forme du superlatif s’emploie après « sein » ?', 'mcq', '["am + -sten","der + -ste","mehr + adjectif","so + adjectif"]'::jsonb, 0, '*Der Zug ist am schnellsten.* La forme en *der/die/das* est réservée à l’épithète.', 1),
    ('74041676-f498-5ea7-a0f6-1489be68877b'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Comment dit-on « le train le plus rapide » ?', 'mcq', '["der schnellste Zug","der Zug am schnellsten","am schnellsten Zug","der schneller Zug"]'::jsonb, 0, 'Épithète : article défini + adjectif au superlatif décliné.', 2),
    ('4138da5f-6c2a-5e86-9768-1884be39e252'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Pourquoi dit-on « am ältesten » et non « am altsten » ?', 'mcq', '["On intercale un e après d, t, s, ß, z","C’est une exception unique","Le e marque le datif","Pour éviter l’Umlaut"]'::jsonb, 0, 'Un *e* de liaison rend la forme prononçable.', 3),
    ('dc16393b-3530-5895-9924-50a274b633fc'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Quel est le superlatif de « gut » ?', 'mcq', '["am besten","am gutsten","am mehrsten","am guten"]'::jsonb, 0, 'Série irrégulière : *gut → besser → am besten*.', 4),
    ('ca04b557-c34c-5ad7-ad1f-75784ebdee8a'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, '« am liebsten » signifie…', 'mcq', '["Ce que je préfère par-dessus tout","Le plus aimé de tous","Avec amour","Aussi volontiers que"]'::jsonb, 0, '*Am liebsten lese ich Krimis* — une tournure très utile pour donner son avis.', 5),
    ('f3e9940c-a0f4-53a2-a804-e6a5e25b0658'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'La forme « am schnellsten » se décline devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est figée ; devant un nom, on passe à *der schnellste*.', 6),
    ('1dcbb459-e078-5847-b21c-27470c9131cc'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Quel est le superlatif de « hoch » ?', 'mcq', '["am höchsten","am hochsten","am höhesten","am hohesten"]'::jsonb, 0, 'Comme *nah → am nächsten* : à apprendre par cœur.', 7),
    ('a94e4767-d7a9-5b20-8cf4-a71d7edd9726'::uuid, 'f9f60879-1ec5-5f08-9f57-f0a3b3c841bf'::uuid, 'Comment introduire le complément d’un superlatif ?', 'mcq', '["von ou unter + datif","als + nominatif","wie + accusatif","für + accusatif"]'::jsonb, 0, '*Er ist der Größte von allen* / *unter seinen Freunden*.', 8),
    ('ba074673-a3bb-5e8a-8d45-a980557bd3b6'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Quelles prépositions régissent toujours l’accusatif ?', 'mcq', '["durch, für, gegen, ohne, um","aus, bei, mit, nach, von","an, auf, in, über, unter","wegen, trotz, während"]'::jsonb, 0, 'Une liste à apprendre en bloc : elle ne dépend jamais du sens.', 1),
    ('e79485bb-41c8-5dec-9f76-f824a719c34d'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Comment traduire « pour mon frère » ?', 'mcq', '["für meinen Bruder","für meinem Bruder","für mein Bruder","für meines Bruders"]'::jsonb, 0, '*für* + accusatif : le masculin devient *meinen*.', 2),
    ('0cf8ac9c-eaff-5aae-8214-ee62da8ee2e9'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, '« gegen acht Uhr » signifie…', 'mcq', '["Vers huit heures","À huit heures précises","Avant huit heures","Contre huit heures"]'::jsonb, 0, 'Pour l’heure précise, c’est *um acht Uhr*.', 3),
    ('0fd8e21f-94a5-5d66-a072-b5ef04fc111f'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Où se place « entlang » ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Devant le verbe"]'::jsonb, 0, '*die Straße entlang* : c’est la seule de la liste à se postposer.', 4),
    ('a7e9ab57-7165-56af-966a-72a6b585a718'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, '« für das » se contracte en « fürs ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *durch das → durchs* et *um das → ums*.', 5),
    ('a2d44d90-3588-5a69-964f-7311848ec2e6'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Comment traduire « sans argent » ?', 'mcq', '["ohne Geld","ohne dem Geld","ohne das Geld haben","ohne Geldes"]'::jsonb, 0, '*ohne* se passe le plus souvent d’article.', 6),
    ('9d829d49-f29a-52d5-ad48-73db4109d585'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, 'Comment traduire « pour apprendre » ?', 'mcq', '["um zu lernen","für lernen","für zu lernen","um lernen"]'::jsonb, 0, '*für* introduit un groupe nominal, jamais un verbe : le but se dit *um… zu*.', 7),
    ('2e083f20-645f-5392-9e7f-3bfc19d06c98'::uuid, '9e94474e-70b3-5431-a89e-6632df4b2ba0'::uuid, '« bis » est souvent suivi d’une seconde préposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*bis zum Bahnhof*, *bis zur Brücke* — et c’est alors elle qui commande le cas.', 8),
    ('1678997f-77d9-50ac-ba1d-0e091bd221d3'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Quelle série de prépositions régit le datif ?', 'mcq', '["aus, bei, mit, nach, seit, von, zu","durch, für, gegen, ohne, um","wegen, trotz, während, statt","an, auf, hinter, in, neben"]'::jsonb, 0, 'La formule *aus-bei-mit-nach-seit-von-zu* se retient d’un bloc.', 1),
    ('8eb8a257-1305-503f-b6b0-341a9c249d7d'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, '« Ich komme aus der Schweiz » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*aus* impose le datif : *die Schweiz* devient *der Schweiz*.', 2),
    ('4e14e6c0-fa45-505e-bc1f-d900c21de014'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'En quoi se contracte « zu der » ?', 'mcq', '["zur","zum","zud","zurd"]'::jsonb, 0, '*zur Schule*, *zur Post*. Et *zu dem → zum*.', 3),
    ('9176ef95-6780-5035-9e08-b2939daf532a'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe nach dem Arzt","Ich gehe bei dem Arzt","Ich gehe in den Arzt"]'::jsonb, 0, '*zu* + personne vue comme un but ; *bei* dirait où l’on se trouve déjà.', 4),
    ('e481bd54-e5fb-5354-bb10-7acf49b9f1d7'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Avec « seit », quel temps emploie-t-on en allemand ?', 'mcq', '["Le présent","Le parfait","Le prétérit","Le futur"]'::jsonb, 0, '*Ich lerne seit drei Jahren Deutsch.*', 5),
    ('9ad468e8-f768-501a-853c-42454ced21fd'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Comment dit-on « je vais en Suisse » ?', 'mcq', '["Ich fahre in die Schweiz","Ich fahre nach die Schweiz","Ich fahre nach der Schweiz","Ich fahre zu Schweiz"]'::jsonb, 0, 'Les pays qui ont un article prennent *in* + accusatif ; les autres, *nach*.', 6),
    ('dcea5ef4-3dad-5061-89f6-bee48870246e'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, '« nach Hause » et « zu Hause » signifient la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*nach Hause* = vers la maison (mouvement), *zu Hause* = à la maison (sans mouvement).', 7),
    ('6f6e921c-573b-5610-88cf-41e20ba7b4a2'::uuid, 'd4f5660d-bc63-5d58-9572-1cb599cc23c1'::uuid, 'Que signifie « bei » dans « beim Essen » ?', 'mcq', '["Pendant, lors de","Après","Sans","Contre"]'::jsonb, 0, '*bei* couvre aussi le moment d’une action en cours.', 8),
    ('ac1c5001-6c5e-5057-b54e-9367b5d9c507'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'Quel cas suit une préposition mixte en cas de déplacement ?', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Question *wohin?* → accusatif. Question *wo?* → datif.', 1),
    ('76f1a656-1656-5d8d-b55c-1c7a7bf37eb5'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, '« Ich bin in der Schule » exprime…', 'mcq', '["Une localisation","Un déplacement","Une possession","Une cause"]'::jsonb, 0, 'Question *wo?* → datif.', 2),
    ('d14ab0e8-910f-55e9-b1f3-db2bc5252e1d'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'Combien y a-t-il de prépositions mixtes ?', 'mcq', '["Neuf","Cinq","Sept","Douze"]'::jsonb, 0, '*an, auf, hinter, in, neben, über, unter, vor, zwischen*.', 3),
    ('87f7fd3a-ffdd-5dfa-9744-e0c29a189528'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'Quel verbe demande le datif : « stehen » ou « stellen » ?', 'mcq', '["stehen","stellen","Les deux","Aucun des deux"]'::jsonb, 0, '*stehen* décrit un état (datif) ; *stellen* un déplacement (accusatif).', 4),
    ('c4112f3d-e1c1-5e34-a1bd-2b9959f35bce'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, '« Ich laufe im Park » signifie que je cours à l’intérieur du parc.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in den Park* dirait que j’y entre. Ce n’est pas le verbe qui décide, mais le changement de lieu.', 5),
    ('18a847fe-bdcf-593e-b6bc-81ab64c7c600'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'En quoi se contracte « in das » ?', 'mcq', '["ins","im","ind","ins dem"]'::jsonb, 0, '*in dem* donne *im* : ne pas les confondre, ils n’ont pas le même cas.', 6),
    ('75fcfa61-0ec5-5ea1-9aaa-7ea4db121b5d'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, 'Comment dit-on « en janvier » ?', 'mcq', '["im Januar","in Januar","am Januar","an Januar"]'::jsonb, 0, 'Emploi figé : *im* + mois et saisons, *am* + jours et dates.', 7),
    ('dcdbe1eb-266b-5b34-b8e8-5f2d9bbb7414'::uuid, '4b92f6de-c55d-51f3-9fa7-16b0cfca2bb2'::uuid, '« sich auf etwas freuen » se construit avec le datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un emploi figé à l’accusatif : *Ich freue mich auf die Ferien.*', 8),
    ('94243ba4-8c8f-5dc7-85b0-593903767d28'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Après « denn », où se place le verbe conjugué ?', 'mcq', '["En deuxième position, comme d’habitude","À la fin de la proposition","En première position","Juste après denn"]'::jsonb, 0, '*denn* est une coordination : il ne compte pas dans l’ordre des mots.', 1),
    ('86a0539d-006d-5aee-87bf-5bf8c07be78f'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Quelle conjonction envoie le verbe à la fin ?', 'mcq', '["weil","denn","aber","und"]'::jsonb, 0, '*weil* subordonne ; *denn* coordonne, pour le même sens.', 2),
    ('b01bebc8-1fdf-51c4-8a9d-f8dc844e140b'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, '« sondern » s’emploie…', 'mcq', '["Après une négation, pour rectifier","Après une affirmation","Pour exprimer la cause","Pour exprimer le but"]'::jsonb, 0, '*Das ist nicht mein Buch, sondern deins.*', 3),
    ('850c88df-017b-524c-98f7-f713d8c629e0'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Que signifie « weder… noch » ?', 'mcq', '["Ni… ni","Ou bien… ou bien","Non seulement… mais aussi","Certes… mais"]'::jsonb, 0, 'La phrase est déjà négative : on n’ajoute pas *nicht*.', 4),
    ('a90a7626-d79b-5393-b5ce-fee4bae036f3'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'La virgule est obligatoire devant « aber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme devant *sondern* et *denn* ; elle est absente devant *und* et *oder*.', 5),
    ('8e1d0bf5-75c2-5087-ae03-1b0dec0586bc'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Dans « Es regnet, deshalb bleibe ich zu Hause », pourquoi « bleibe » précède-t-il « ich » ?', 'mcq', '["Parce que deshalb occupe la première position","Parce que c’est une subordonnée","Parce que deshalb est une conjonction","C’est une faute"]'::jsonb, 0, '*deshalb* est un adverbe : il prend la première place et provoque l’inversion.', 6),
    ('9af96849-cdf5-5635-8eca-3e89ed31ade7'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, '« entweder… oder » signifie « ou bien… ou bien ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À ne pas confondre avec *sowohl… als auch*, « aussi bien… que ».', 7),
    ('3edb6e55-ef58-5985-ab1a-302a33af3a9e'::uuid, '0fe8f804-b7e2-5de3-95b6-0f4c147fdf57'::uuid, 'Quelle conjonction s’emploie sans négation devant, pour opposer ?', 'mcq', '["aber","sondern","weder","denn"]'::jsonb, 0, '*Er ist arm, aber glücklich.* *sondern* exige une négation devant lui.', 8),
    ('17043743-52e4-5cd5-bb0d-e46f21369417'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Quelle question appelle un complément de lieu au datif ?', 'mcq', '["wo?","wohin?","woher?","wann?"]'::jsonb, 0, '*wo?* = localisation → datif. *wohin?* = déplacement → accusatif.', 1),
    ('4087a3fb-467b-5a33-b3e3-61a16af47d8c'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe beim Arzt","Ich gehe nach dem Arzt","Ich gehe in Arzt"]'::jsonb, 0, '*zu* pour la destination, *bei* pour la localisation : *beim Arzt sein*.', 2),
    ('ce32d4fa-d4d9-58d9-864a-5906b6e20579'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Comment dit-on « je viens de France » ?', 'mcq', '["Ich komme aus Frankreich","Ich komme von Frankreich","Ich komme nach Frankreich","Ich komme in Frankreich"]'::jsonb, 0, '*aus* + pays d’origine ; *von* marque un point de départ ou une personne.', 3),
    ('bc128f65-c47b-5c18-ab65-a9af9978f729'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, '« nach » s’emploie devant un pays qui a un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec article, c’est *in* + accusatif : *in die Schweiz*, *in die Türkei*.', 4),
    ('a0424d37-4bc1-53ee-84cb-933818b779ea'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Que signifie « auf dem Land » ?', 'mcq', '["À la campagne","Sur le pays","Au bord de la mer","À l’étranger"]'::jsonb, 0, 'Et *aufs Land* pour le déplacement : *Wir fahren aufs Land.*', 5),
    ('0850fdd1-2103-5a34-973b-8770b44ccdc3'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Que marque la particule « her » ?', 'mcq', '["Le rapprochement vers le locuteur","L’éloignement du locuteur","La répétition","Le passé"]'::jsonb, 0, '*Komm her!* — *hin* marque au contraire l’éloignement.', 6),
    ('49476812-c8fa-532a-a527-4de0181e77cc'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, '« Wo gehst du hin? » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La particule de *wohin* peut se détacher et partir en fin de phrase.', 7),
    ('ecfc4555-b363-5db8-b848-1888fc482ea8'::uuid, 'b9542811-fc65-509b-8db1-396996a9bcc6'::uuid, 'Comment dit-on « je rentre à la maison » ?', 'mcq', '["Ich gehe nach Hause","Ich gehe zu Hause","Ich gehe in Hause","Ich gehe im Haus"]'::jsonb, 0, '*nach Hause* pour le mouvement, *zu Hause* pour l’état.', 8),
    ('7e325a22-adcb-5c29-99c9-70b496d2f92c'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Comment dit-on « le lundi » (un lundi précis) ?', 'mcq', '["am Montag","im Montag","um Montag","in Montag"]'::jsonb, 0, '*am* + jours et parties de la journée.', 1),
    ('1aacaa6a-c46f-5cf6-8ad4-da46c309d9e4'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Comment dit-on « en été » ?', 'mcq', '["im Sommer","am Sommer","um Sommer","in Sommer"]'::jsonb, 0, '*im* + mois, saisons et années.', 2),
    ('7cea1954-6076-5209-83ef-b91cc636d9e8'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Comment dit-on « à huit heures » ?', 'mcq', '["um acht Uhr","am acht Uhr","im acht Uhr","in acht Uhr"]'::jsonb, 0, '*um* + heure précise.', 3),
    ('cbeddec8-759d-5d31-9120-6a7aefbe0f0b'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, '« jeden Tag » est au…', 'mcq', '["Accusatif, sans préposition","Datif, sans préposition","Génitif","Nominatif"]'::jsonb, 0, 'Durées et dates entières se mettent à l’accusatif nu : *letzte Woche*, *den ganzen Tag*.', 4),
    ('a78c4a83-744b-50f7-8d4a-57a52a71c7d8'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Comment dit-on « il y a deux semaines » ?', 'mcq', '["vor zwei Wochen","seit zwei Wochen","in zwei Wochen","ab zwei Wochen"]'::jsonb, 0, '*vor* + datif pour le passé ; *in* + datif pour le futur.', 5),
    ('a61e0360-5db2-5637-a1cd-024defbdfd75'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, '« morgens » signifie « demain ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*morgen* = demain, *morgens* = le matin (habituellement).', 6),
    ('afc2fb43-44a3-52e9-bb39-c5696607a3e2'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","seit","ab","bis"]'::jsonb, 0, '*während der Ferien*, *während des Sommers*.', 7),
    ('bc1ff034-76f0-585d-9bfa-456649e4ebc1'::uuid, '39bc781c-b438-5c6a-9b67-4c478b2e2e54'::uuid, 'Où se place le complément de temps parmi les compléments ?', 'mcq', '["En premier","En dernier","Après le lieu","Après la manière"]'::jsonb, 0, 'C’est le *Te* de TeKaMoLo : temps, cause, manière, lieu.', 8),
    ('851894d0-bb2f-518d-a453-0952b831178d'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Quel auxiliaire s’emploie au parfait avec les verbes de mouvement ?', 'mcq', '["sein","haben","werden","lassen"]'::jsonb, 0, '*Ich bin gefahren*, *ich bin gegangen*.', 1),
    ('e0bff566-9c9a-5e0c-8515-dd612142e581'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Quel est le prétérit de « haben » à la 1re personne ?', 'mcq', '["ich hatte","ich habte","ich hatt","ich war"]'::jsonb, 0, 'Verbe mixte : radical modifié + terminaison faible.', 2),
    ('dc515889-d6d3-54db-99f5-1a9d78b96d6d'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, '« werden » sert d’auxiliaire au futur ET au passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich werde kommen* (futur) / *Das Haus wird gebaut* (passif).', 3),
    ('5b9ddca3-6ef6-5b59-ae0c-278d516d1dd9'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Comment se conjugue « sein » à la 2e personne du pluriel ?', 'mcq', '["ihr seid","ihr sind","ihr seit","ihr bist"]'::jsonb, 0, '*seid* avec un d — *seit* avec un t est la préposition « depuis ».', 4),
    ('6346404c-9afd-514e-8397-f79e57aca1e4'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Que signifie « bekommen » ?', 'mcq', '["Recevoir","Devenir","Venir","Convenir"]'::jsonb, 0, 'Faux ami classique : « devenir » se dit *werden*.', 5),
    ('5c98cc61-a82b-514a-9efe-78e98a7a350a'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, '« Ich habe das Auto gefahren » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Employé avec un COD, un verbe de mouvement prend *haben*.', 6),
    ('219c1b36-f224-5167-a5fb-da395970532f'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Quel est le participe passé de « werden » dans un passif ?', 'mcq', '["worden","geworden","gewerdet","werdet"]'::jsonb, 0, '*geworden* est réservé au verbe plein : *Er ist Arzt geworden.*', 7),
    ('97d524f1-086c-55a0-a95b-960e0d788e46'::uuid, '58476db8-0413-5f5a-9055-f3477a2945c7'::uuid, 'Quel auxiliaire prend « bleiben » au parfait ?', 'mcq', '["sein","haben","werden","les deux au choix"]'::jsonb, 0, '*Ich bin zu Hause geblieben*, comme *sein* et *passieren*.', 8),
    ('dea88c12-ba66-512d-9f6a-d179109b34d5'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Qu’appelle-t-on les trois temps primitifs d’un verbe ?', 'mcq', '["Infinitif, prétérit, participe II","Présent, futur, passé","Infinitif, présent, parfait","Radical, préverbe, terminaison"]'::jsonb, 0, 'Avec eux, toute la conjugaison se déduit.', 1),
    ('13f63370-d460-58e5-9223-9771d05558a3'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Quel est le participe passé de « spielen » ?', 'mcq', '["gespielt","gespielen","spielte","gespiel"]'::jsonb, 0, 'Verbe faible : *ge-* + radical + *-t*.', 2),
    ('5fb4a00b-b721-5103-b233-1cc0ece6d1c4'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Un verbe fort change de voyelle au prétérit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’alternance vocalique : *sprechen → sprach*, *fahren → fuhr*.', 3),
    ('d3945f84-2de6-5d8b-b1f0-9493cddf1e14'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Comment se conjugue « geben » à la 3e personne du singulier ?', 'mcq', '["er gibt","er gebt","er gab","er gibst"]'::jsonb, 0, 'Alternance *e → i* aux 2e et 3e personnes du singulier seulement.', 4),
    ('9d56a2a3-c207-5bc1-a6e6-757a01428936'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Comment se conjugue « fahren » à la 2e personne du singulier ?', 'mcq', '["du fährst","du fahrst","du fuhrst","du fährt"]'::jsonb, 0, 'Alternance *a → ä*, qui disparaît au pluriel.', 5),
    ('7e915eed-03f5-50b1-bc47-06cc3791255f'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, '« bringen → brachte → gebracht » est un verbe…', 'mcq', '["Mixte","Faible régulier","Fort","Irrégulier isolé"]'::jsonb, 0, 'Radical modifié mais terminaisons faibles, comme *denken* et *wissen*.', 6),
    ('7fcff254-09f2-52d1-8b40-14bdba295740'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Les verbes en -ieren prennent « ge- » au participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*studiert*, *telefoniert*, *fotografiert* : jamais de *ge-*.', 7),
    ('76880c93-5694-562a-a10f-1e002726634e'::uuid, '164ea143-a145-54fd-8930-8810a3bb70d6'::uuid, 'Quel est le prétérit de « schreiben » ?', 'mcq', '["schrieb","schreibte","schrob","geschrieben"]'::jsonb, 0, 'Verbe fort : *schreiben → schrieb → geschrieben*.', 8),
    ('a3696cc1-2e02-54bd-b715-9814cc13a494'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Où se place l’infinitif dépendant d’un modal, dans une principale ?', 'mcq', '["À la fin de la phrase","Juste après le modal","Devant le sujet","En première position"]'::jsonb, 0, '*Ich muss heute Abend arbeiten.*', 1),
    ('abe6ec21-9837-5a43-98c2-3b37b7de334c'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Comment se conjugue « können » à la 1re personne du singulier ?', 'mcq', '["ich kann","ich könne","ich kanne","ich könnt"]'::jsonb, 0, 'Les modaux n’ont aucune terminaison aux 1re et 3e personnes du singulier.', 2),
    ('a9a8f592-dbd1-5884-8ae4-ea2a8c000932'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, '« Ich muss nicht kommen » signifie…', 'mcq', '["Je ne suis pas obligé de venir","Je ne dois pas venir","Je ne peux pas venir","Je ne veux pas venir"]'::jsonb, 0, 'L’interdiction se dit *nicht dürfen* : *Du darfst nicht kommen.*', 3),
    ('3ee31466-4e68-5cf6-ad1f-97088f3778d6'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Quel modal exprime une consigne venue d’autrui ?', 'mcq', '["sollen","wollen","können","mögen"]'::jsonb, 0, '*Ich soll den Arzt fragen* : on m’a dit de le faire.', 4),
    ('3426b7ce-2a10-506c-9a1a-8c0443f4d717'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Quel est le prétérit de « müssen » ?', 'mcq', '["musste","müsste","mochte","gemusst"]'::jsonb, 0, 'Sans inflexion : *musste*. *müsste* est le subjonctif II.', 5),
    ('686d4b2d-f686-5b9f-9ab7-8dcc6fb7be7b'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Au parfait, avec un infinitif dépendant, le modal prend la forme du participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le double infinitif : *Ich habe arbeiten müssen.*', 6),
    ('a4af09d8-b384-5d38-a082-65678e8728c5'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Comment dire poliment « je voudrais un café » ?', 'mcq', '["Ich möchte einen Kaffee","Ich will einen Kaffee","Ich mag einen Kaffee","Ich muss einen Kaffee"]'::jsonb, 0, '*möchte* est le subjonctif II de *mögen* : la forme polie usuelle.', 7),
    ('a13ed2cd-1266-5ecc-aa97-57ea36db5d40'::uuid, 'd1d075dc-35b9-584c-9d56-ab6a6e073524'::uuid, 'Quel modal exprime l’autorisation ?', 'mcq', '["dürfen","müssen","wollen","sollen"]'::jsonb, 0, '*Darf ich reinkommen?* — *können* dit la capacité.', 8),
    ('0b4f6017-3107-5b4c-aaa8-39f6746806af'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Comment reconnaître un préverbe séparable ?', 'mcq', '["Il porte l’accent du mot","Il commence par be-","Il se termine par -en","Il est toujours plus long"]'::jsonb, 0, '*ÁNrufen* contre *be-SÚCHEN* : le critère s’entend.', 1),
    ('0ca75619-ada6-565a-af00-ce2be428148e'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Dans une principale, où va le préverbe séparable ?', 'mcq', '["À la fin de la phrase","Devant le verbe","Après le sujet","Il reste soudé"]'::jsonb, 0, '*Ich stehe um sieben Uhr auf.*', 2),
    ('e8d8502b-60e8-5ad0-9366-fa719fd19638'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Quel est le participe passé de « aufstehen » ?', 'mcq', '["aufgestanden","geaufstanden","aufstanden","gestandenauf"]'::jsonb, 0, 'Le *ge-* s’intercale entre le préverbe et le radical.', 3),
    ('ef9b6eed-5aec-5fba-aff1-744d24f00d99'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Quel est le participe passé de « besuchen » ?', 'mcq', '["besucht","gebesucht","besuchen","gesucht"]'::jsonb, 0, 'Les préverbes inséparables (*be-, ver-, er-, ent-*) interdisent le *ge-*.', 4),
    ('80ebdd9e-e550-5873-8312-f8afce78f78d'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Comment écrit-on « einkaufen » avec « zu » ?', 'mcq', '["einzukaufen","zu einkaufen","einkaufen zu","zueinkaufen"]'::jsonb, 0, 'Le *zu* s’intercale, et le tout s’écrit en un seul mot.', 5),
    ('6925d6fc-5fbb-5de0-9025-249d87086d5e'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'En subordonnée, le préverbe reste détaché.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le verbe conjugué part à la fin et rejoint son préverbe : *…, weil er aufsteht.*', 6),
    ('42440865-4db5-5d1f-beb0-4f3a6bdead41'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, '« übersetzen » est toujours inséparable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Séparable au sens concret (traverser), inséparable au sens figuré (traduire).', 7),
    ('a0bd0ffc-bddc-5264-a592-5c00444bd260'::uuid, 'ec6c70ce-d35b-5da0-9c0c-667e803d202a'::uuid, 'Que signifie « ankommen » ?', 'mcq', '["Arriver","Venir","Recevoir","Accompagner"]'::jsonb, 0, '*bekommen* = recevoir, *mitkommen* = accompagner : le préverbe fait le sens.', 8),
    ('92678824-2f87-5591-8dbb-8ccf00dcb191'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Quelle est la forme du réfléchi à la 3e personne, à l’accusatif comme au datif ?', 'mcq', '["sich","ihn","ihm","es"]'::jsonb, 0, '*sich* couvre les deux cas à la 3e personne, singulier et pluriel.', 1),
    ('256c3a84-6dfc-575f-9455-4f174821202a'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Quand emploie-t-on le réfléchi au datif ?', 'mcq', '["Quand la phrase contient déjà un COD","Quand le verbe est fort","Quand la phrase est négative","Quand le sujet est au pluriel"]'::jsonb, 0, '*Ich wasche mir die Hände* : *die Hände* est le COD.', 2),
    ('919b9b5f-f0f4-538e-87ae-46e1ad24b468'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Comment dit-on « je me lave » (sans complément) ?', 'mcq', '["Ich wasche mich","Ich wasche mir","Ich wasche mich die","Ich wasche sich"]'::jsonb, 0, 'Sans COD, le réfléchi reste à l’accusatif.', 3),
    ('deaf30ec-7271-51fb-9cc1-e4b31bbc4755'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Où se place le pronom réfléchi dans une principale ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Devant le sujet toujours","Après le participe passé"]'::jsonb, 0, '*Ich freue mich auf die Ferien.*', 4),
    ('3474888c-c1af-5a81-8114-2e38df43cb42'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, '« sich freuen auf » se construit avec…', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Comme *sich interessieren für* et *sich erinnern an* : préposition + accusatif.', 5),
    ('83090dca-4e6a-5da5-8e2d-fd5dad4b6444'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, '« aufstehen » est un verbe pronominal en allemand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Se lever » se dit *aufstehen*, sans pronom réfléchi.', 6),
    ('2cc00c56-46c4-566a-afbc-95a9c61cb117'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Dans le vouvoiement, « sich » prend une majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Setzen Sie sich bitte!* — seul *Sie* et ses formes possessives la prennent.', 7),
    ('fa178e39-2938-5890-bb79-b11e58cb099f'::uuid, 'b6e3db9e-8dab-58ba-bb17-b19ac8c106e7'::uuid, 'Comment dit-on « je m’achète un livre » ?', 'mcq', '["Ich kaufe mir ein Buch","Ich kaufe mich ein Buch","Ich kaufe sich ein Buch","Ich kaufe mein Buch"]'::jsonb, 0, 'Il y a un COD (*ein Buch*) : le réfléchi passe au datif.', 8),
    ('e2309277-a912-5c70-abfe-13863eaef537'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Quelle est la terminaison de la 2e personne du singulier ?', 'mcq', '["-st","-t","-e","-en"]'::jsonb, 0, '*du spielst*, *du lernst*, *du wohnst*.', 1),
    ('66e1477a-fcd5-54e1-a0ca-d60391d510dc'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Comment se conjugue « arbeiten » à la 3e personne du singulier ?', 'mcq', '["er arbeitet","er arbeitt","er arbeit","er arbeitest"]'::jsonb, 0, 'Radical en *-t* : on intercale un *e* pour pouvoir prononcer.', 2),
    ('f7acd4ed-44df-5042-b1d8-2562c00a700d'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Comment se conjugue « heißen » à la 2e personne du singulier ?', 'mcq', '["du heißt","du heißst","du heißest","du heißen"]'::jsonb, 0, 'Après *-s, -ß, -z*, le *-st* perd son *s*.', 3),
    ('bac5d7f6-40b2-5a03-bf68-90e29a4c8e41'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Le changement de voyelle des verbes forts touche aussi le pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne concerne que les 2e et 3e personnes du singulier : *wir fahren*, pas *wir fähren*.', 4),
    ('3878a9c9-e39d-532d-ac62-2731640ae187'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Comment se conjugue « lesen » à la 3e personne du singulier ?', 'mcq', '["er liest","er lest","er läst","er liesst"]'::jsonb, 0, 'Alternance *e → ie*, et le *-st* fusionne avec le *s* du radical.', 5),
    ('26d60cd8-505d-55ef-a3f8-1fa355da268a'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Comment traduire « demain, je vais à Berlin » ?', 'mcq', '["Morgen fahre ich nach Berlin","Morgen ich fahre nach Berlin","Morgen werde ich fahren nach Berlin","Morgen ich werde nach Berlin"]'::jsonb, 0, 'Le présent suffit à dire l’avenir dès qu’un adverbe de temps le précise.', 6),
    ('e4bbbfe6-5acf-5bd0-be7a-df77ce6fb2d8'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Avec « seit », l’allemand emploie le parfait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le présent : *Ich lerne seit drei Jahren Deutsch.*', 7),
    ('cc78e90a-4056-572f-8969-0ed7686ff75c'::uuid, 'f77237a0-3007-5e64-ad4d-c2142aae2561'::uuid, 'Comment se conjugue « werden » à la 2e personne du singulier ?', 'mcq', '["du wirst","du werdest","du werdst","du wird"]'::jsonb, 0, '*werde, wirst, wird, werden, werdet, werden*.', 8),
    ('391c2d62-ff4f-5107-af91-6eacb8593765'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Le prétérit est le temps…', 'mcq', '["De l’écrit et du récit","De l’oral courant","Du futur proche","De l’hypothèse"]'::jsonb, 0, 'À l’oral, on raconte au parfait — sauf pour *sein*, *haben* et les modaux.', 1),
    ('de19df76-c724-50fe-be14-9a93d46ab8bd'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quelle est la marque du prétérit des verbes faibles ?', 'mcq', '["-te","-en","-st","Un changement de voyelle"]'::jsonb, 0, '*ich spielte*, *er spielte* : les deux formes sont identiques.', 2),
    ('f4c25c53-46bb-595a-8e75-755f6f26bff5'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quel est le prétérit de « gehen » ?', 'mcq', '["ging","gehte","gang","gegangen"]'::jsonb, 0, 'Verbe fort : *gehen → ging → gegangen*.', 3),
    ('7ee9d0cc-3ea0-53c9-adac-ddefd8959dc9'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Aux 1re et 3e personnes, un verbe fort au prétérit ne prend aucune terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*ich ging*, *er ging* : la forme est nue.', 4),
    ('6ec2ccea-9402-5169-91b8-9149fa2a2aae'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quel est le prétérit de « wissen » ?', 'mcq', '["wusste","wisste","wieß","gewusst"]'::jsonb, 0, 'Verbe mixte : radical modifié, terminaison faible.', 5),
    ('929a6e0d-c7a2-5006-bd68-dfd8b57632ea'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quels verbes emploie-t-on au prétérit même à l’oral ?', 'mcq', '["sein, haben, werden et les modaux","Tous les verbes forts","Les verbes en -ieren","Aucun"]'::jsonb, 0, '*Ich war müde* est bien plus naturel que *ich bin müde gewesen*.', 6),
    ('2c1e02b4-5b5a-5f78-a849-7a14ba8d6fe6'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Prétérit de haben ou sein + participe II","Présent de werden + infinitif","Prétérit + zu","Parfait + würde"]'::jsonb, 0, '*Ich hatte gegessen*, *er war gegangen* — surtout après *nachdem*.', 7),
    ('d7d072a0-67e5-5003-afd4-1ea1c0be6283'::uuid, '941f9c2c-cd65-5245-b194-9bcacaa95888'::uuid, 'Quel est le prétérit de « nehmen » ?', 'mcq', '["nahm","nehmte","nimmte","genommen"]'::jsonb, 0, 'Alternance forte : *nehmen → nahm → genommen*.', 8),
    ('40b54402-05a3-5184-89aa-07ddba4bc699'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Où se place le participe II dans une principale au parfait ?', 'mcq', '["À la fin de la phrase","Juste après l’auxiliaire","En deuxième position","Devant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : l’auxiliaire ouvre, le participe ferme.', 1),
    ('759ba45e-2c3d-5e14-bc74-deade6bba66d'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Quel est le participe II de « fahren » ?', 'mcq', '["gefahren","gefahrt","fahren","gefuhr"]'::jsonb, 0, 'Verbe fort : *ge-* + radical + *-en*.', 2),
    ('9d9e53f2-c594-5c5c-9d5e-464dbdbcff16'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Quel auxiliaire prend « einschlafen » au parfait ?', 'mcq', '["sein","haben","werden","Les deux"]'::jsonb, 0, 'C’est un verbe de changement d’état : *Ich bin eingeschlafen.*', 3),
    ('e16d720e-1d31-5018-b242-0c2b76ee54ac'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Quel est le participe II de « telefonieren » ?', 'mcq', '["telefoniert","getelefoniert","telefonierte","getelefonierte"]'::jsonb, 0, 'Les verbes en *-ieren* n’ont jamais de *ge-*.', 4),
    ('e3afd7f0-487d-5645-b495-d61a9c74cca9'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Quel est le participe II de « einkaufen » ?', 'mcq', '["eingekauft","geeinkauft","einkauft","gekaufein"]'::jsonb, 0, 'Préverbe séparable : le *ge-* s’intercale.', 5),
    ('bd7edda0-4b2b-5d76-9cbc-77c9e161dc4a'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, '« Ich habe das Auto gefahren » est une faute.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Employé avec un COD, *fahren* prend *haben*.', 6),
    ('49ba31a0-9c9b-5f28-98e3-22ddb2351d97'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'En subordonnée, où se place l’auxiliaire au parfait ?', 'mcq', '["Après le participe, à la toute fin","En deuxième position","Devant le participe","Il disparaît"]'::jsonb, 0, '*…, weil ich einen Film gesehen habe.*', 7),
    ('98bf6300-9d36-5d5a-9648-fc7019725c5b'::uuid, '67a461a1-6c1d-5610-a468-34b4169faa37'::uuid, 'Le parfait est le passé de la conversation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le prétérit, lui, est celui du récit écrit.', 8),
    ('e7706aa3-6e52-593a-b2a1-106c503a6fe1'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Comment se forme le Futur I ?', 'mcq', '["werden + infinitif","sein + participe II","haben + infinitif","werden + participe II"]'::jsonb, 0, '*Ich werde morgen fahren*, l’infinitif en fin de phrase.', 1),
    ('0fa73692-a097-51f1-8f7f-c536d14124d4'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Comment se conjugue « werden » à la 3e personne du singulier ?', 'mcq', '["er wird","er werd","er werdet","er wurde"]'::jsonb, 0, '*ich werde, du wirst, er wird…*', 2),
    ('5c7c7392-ca74-58c5-880f-f5549819c404'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Quand le présent suffit-il à exprimer le futur ?', 'mcq', '["Quand un adverbe de temps précise l’avenir","Jamais","Uniquement avec les modaux","Uniquement à l’écrit"]'::jsonb, 0, '*Morgen fahre ich nach Berlin* est la forme la plus courante.', 3),
    ('bb49eab1-cafb-5f8b-8687-52302876c708'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, '« Er wird wohl krank sein » signifie…', 'mcq', '["Il doit être malade (supposition)","Il sera malade demain","Il est tombé malade","Il veut être malade"]'::jsonb, 0, 'Le futur exprime aussi une hypothèse sur le présent, souvent avec *wohl*.', 4),
    ('bef44999-d842-5b90-be8a-701c4cf2e6c6'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, '« Das Haus wird gebaut » est un futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un passif : *werden* + participe II. Le futur demanderait un infinitif.', 5),
    ('bc37c33c-692a-563f-be64-83d3064d6aea'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Que signifie « Er wird Arzt » ?', 'mcq', '["Il devient médecin","Il sera médecin demain","Il est fait médecin","Il doit être médecin"]'::jsonb, 0, '*werden* + nom : c’est le verbe plein « devenir ».', 6),
    ('9999cc54-8665-5619-9db8-4859020ce5b2'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'En subordonnée, quel mot ferme une phrase au futur ?', 'mcq', '["werden conjugué","L’infinitif","Le sujet","La conjonction"]'::jsonb, 0, '*…, dass er kommen wird.*', 7),
    ('9e374079-c62d-5068-80fe-3cbbc5389c9f'::uuid, '13cad8cd-49ce-5a3e-a182-36f6a4727f6a'::uuid, 'Le Futur II exprime une action achevée dans l’avenir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Bis morgen werde ich das Buch gelesen haben* — ou une supposition sur le passé.', 8),
    ('13996195-322f-5f24-ac87-91d14560cb70'::uuid, '3404fcd9-51b2-573b-bc91-c69d8cf0c16e'::uuid, 'Quelle est la forme d’impératif de « kommen » pour « du » ?', 'mcq', '["Komm!","Kommst!","Komme du!","Kommen!"]'::jsonb, 0, 'Radical sans terminaison et sans pronom.', 1),
    ('4dd6ca21-8f48-5d56-898d-634ce026c72d'::uuid, '3404fcd9-51b2-573b-bc91-c69d8cf0c16e'::uuid, 'Comment dit-on « Donne ! » (du) ?', 'mcq', '["Gib!","Geb!","Gebe!","Gibst!"]'::jsonb, 0, 'L’alternance *e → i* se maintient à l’impératif.', 2),
    ('caf6a316-942e-57bd-b12b-202a115a67d3'::uuid, '3404fcd9-51b2-573b-bc91-c69d8cf0c16e'::uuid, '« Fahre! » garde-t-il l’inflexion de « du fährst » ?', 'mcq', '["Non, on dit Fahr!","Oui, on dit Fähr!","Oui, on dit Fährst!","Les deux sont possibles"]'::jsonb, 0, 'L’alternance *a → ä* disparaît à l’impératif.', 3),
